def rebalance(questions):
    for i, q in enumerate(questions):
        target = i % 4
        a = q["ans"]
        if a != target:
            q["opts"][a], q["opts"][target] = q["opts"][target], q["opts"][a]
            q["ans"] = target
    return questions


def main():
    root = os.getcwd()
    with io.open(os.path.join(root, INIT), encoding="utf-8") as f:
        init = f.read()
    with io.open(os.path.join(root, DATA_PATH), encoding="utf-8") as f:
        data = json.load(f)
    with io.open(os.path.join(root, SEEDER_PATH), encoding="utf-8") as f:
        seeder = f.read()

    if "advanced_sysadmin" in data:
        print("Already applied. Nothing to do.")
        return
    if '"3.143.0"' not in init:
        sys.exit("ABORT: not at v3.143.0.")

    old_order = 'ORDER = ["sysadmin_function", "users_permissions", "master_governance", "backups_continuity", "changes_updates", "email_integrations", "monitoring_health"]'
    new_order = 'ORDER = ["sysadmin_function", "users_permissions", "master_governance", "backups_continuity", "changes_updates", "email_integrations", "monitoring_health", "advanced_sysadmin"]'
    if seeder.count(old_order) != 1:
        sys.exit(f"ABORT: seeder ORDER anchor not found exactly once ({seeder.count(old_order)}).")

    problems = []
    if len(LESSONS) != 9:
        problems.append(f"  {len(LESSONS)} lessons (want 9)")
    short = [f"{l['title'][:40]} ({len(l['html'])})" for l in LESSONS if len(l["html"]) < 2500]
    if short:
        problems.append(f"  below manual depth: {short}")
    if len(QUESTIONS) != 35:
        problems.append(f"  {len(QUESTIONS)} questions (want 35)")
    for q in QUESTIONS:
        if len(q["opts"]) != 4 or not (0 <= q["ans"] <= 3):
            problems.append(f"  malformed '{q['q'][:40]}'")
    if "ERPNext" in json.dumps({"l": LESSONS, "q": QUESTIONS}):
        problems.append("  ERPNext branding leakage")
    if problems:
        print("ABORT — not clean:")
        print("\n".join(problems))
        sys.exit(1)

    bank = rebalance(list(QUESTIONS))
    dist = {c: sum(1 for q in bank if q["ans"] == i) for i, c in enumerate("ABCD")}
    if max(dist.values()) > 10:
        print(f"ABORT — spread failed: {dist}")
        sys.exit(1)

    total = sum(len(l["html"]) for l in LESSONS)
    print(f"Sysadmin 8: 9 chapters ({total:,} chars, min {min(len(l['html']) for l in LESSONS):,}), bank {len(bank)}, spread {dist}")

    if CHECK_ONLY:
        print("--check given; no files written.")
        return

    data["advanced_sysadmin"] = {
        "title": "Sysadmin 8 — Advanced Sysadmin: Security, Audit & Structure",
        "desc": "The structural layer closing the platform certification: the security constitution with tiered 2FA and sessions, the audit trail configured and proven, the five-verb incident procedure, the watched watcher's conduct standard, the sysadmin calendar with names, the handover test for the platform's single-head, and the owner's four-line page answered by pointing — completing the ZhiftERP Sysadmin Professional track and the seven-track academy.",
        "lessons": LESSONS,
        "questions": bank,
    }
    with io.open(os.path.join(root, DATA_PATH), "w", encoding="utf-8") as f:
        json.dump(data, f, indent=1, ensure_ascii=False)
        f.write("\n")
    with io.open(os.path.join(root, SEEDER_PATH), "w", encoding="utf-8") as f:
        f.write(seeder.replace(old_order, new_order, 1))
    with io.open(os.path.join(root, INIT), "w", encoding="utf-8") as f:
        f.write(init.replace('"3.143.0"', '"3.144.0"'))
    print("  data: Sysadmin 8 appended; seeder ORDER extended — TRACK COMPLETE, ACADEMY AT SEVEN TRACKS")
    print("wrote __version__ -> 3.144.0")


if __name__ == "__main__":
    main()
